size_t RegisterJPEGImage(void) {
  MagickInfo
    *magick_info;

  MagickBooleanType
    status;

  /* Initialize version and description for the JPEG format */
  static const char *jpeg_version = ConstantString("JPEG 1.0");
  static const char *jpeg_description = ConstantString("JPEG (Joint Photographic Experts Group)");

  /* Create and configure the MagickInfo entry for "JPEG" */
  magick_info = AcquireMagickInfo("JPEG", "JPE", jpeg_description);
  magick_info->decoder = JPEGReadImage;
  magick_info->encoder = JPEGWriteImage;
  magick_info->thread_support = MagickTrue;

  /* Check the JPEG library version to conditionally enable thread support */
  if (JPEG_LIB_VERSION < 70)
    magick_info->thread_support = MagickFalse;

  magick_info->mime_type = ConstantString("image/jpeg");
  magick_info->note = ConstantString(jpeg_version);
  status = RegisterMagickInfo(magick_info);

  /* Create and configure the MagickInfo entry for "JPEG" */
  magick_info = AcquireMagickInfo("JPEG", "JPEG", jpeg_description);
